/**
 * Source data for the Psychic Powers and Theurgic Rites compendiums
 * (Core Rules Chapter Five, p.128–p.160).
 *
 * Extracted from the rulebook and checked against the path and sect headings.
 * The core rules give one representative power per level per path, and do not
 * reveal the tenth levels: "Only one representative power is given per level in
 * the examples below. Also, the tenth levels are not revealed here, as they are
 * far beyond the ken of beginning characters." (p.128)
 *
 * Paths are bought consecutively — level N requires level N-1 of the same path
 * (p.128) — so each entry names its prerequisite explicitly. Two paths do not
 * begin at level 1: Sympathy starts at 3 and Omen at 6, which is why the chain
 * is stored rather than inferred from the level number.
 */

/** Psychic powers, by path (p.131–p.143). */
export const PSI_POWERS = [
  { n: "Lifting Hand", path: "FarHand", lvl: 1, roll: "Extrovert + Focus", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The first level of FarHand enables the psychic to generate a simple field of directional force which can either slowly lift a single object up (1 meter per turn) OR move it to one side (but not both—that requires another separate field). A maximum weight equal to 25 kg per level of the psychic’s Wits may be lifted. (Additional mass can be bought at 10 kg per Wyrd point.) The only limit to how high an object can be lifted is the range of the power when activated. Once the duration is exceeded, the object will drop from whatever height it was raised to." },
  { n: "Throwing Hand", path: "FarHand", lvl: 2, roll: "Passion + Focus", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic can perform simple manipulations of two such directional fields, enabling her to both lift AND propel an object with appreciable velocity and force. A maximum weight equal to 10 kg per level of the psychic’s Wits may be thrown. (Additional mass can be bought at 5 kg per Wyrd point.) When aiming at a moving target (another person), the psychic must roll Passion+Throwing. Damage is determined by the object thrown (the gamemaster should declare a base damage for the object, using the weapon damages given in Chapter Six: Combat, p.186, as a guideline) plus the victory dice gained…" },
  { n: "Crushing Hand", path: "FarHand", lvl: 3, roll: "Extrovert + Fight", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "This slightly more complex manipulation involves turning two or more directional forces against themselves, enabling the psychic to hold an object steady (when it is being pushed by normal physical forces from varying directions), or crush it altogether. To hold an object, use the grappling rules (Chapter Six: Combat, p.164), substituting the above roll. To punch a target with Crushing Hand, the above roll is used as a goal roll. The damage is 3 plus any victory dice gained from the activation roll. Wyrd points only have to be spent when the power is activated, not for every punch or grapple." },
  { n: "Dueling Hand", path: "FarHand", lvl: 4, roll: "Extrovert + Melee of Shoot", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "Complex and precise manipulations of single objects are now possible, enabling the psychic to operate a machine or fight with melee weapons or firearms using only the mind. CHAPTER FIVE: OCCULT 133 133 A successful activation roll must be made to lift a weapon into the air, after which the weapon remains aloft under the mental control of the psychic for the duration of the power. However, she must make a successful Extrovert+Melee or Shoot roll to swing or fire the weapon at a target (although she does not have to spend more Wyrd)." },
  { n: "FarArms", path: "FarHand", lvl: 5, roll: "Extrovert + Focus", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic can use all the previous powers in combination to lift, throw, hold or manipulate a number of objects equal to his Wits rating." },
  { n: "FarWall", path: "FarHand", lvl: 6, roll: "Extrovert + Stoic Mind", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The simple directional force field can now be expanded and broadened into a force barrier, similar to that generated by energy shield technology. The intensity of the barrier, as well as its shape and position, can be modulated by the psychic to allow for air flow, letting friends in while keeping foes out, and directing attacks to the outside of the barrier. The maximum armor rating for a FarWall is 10d+victory points; the minimum amount of damage which will activate the FarWall is equal to the psychic’s Urge. (If she has no Urge, then 1 point is the minimum.) The gamemaster may require…" },
  { n: "AirStride", path: "FarHand", lvl: 7, roll: "Extrovert + Focus", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic focuses directional forces upon herself sufficient to lift her body off the ground and even cruise at a maximum velocity of 10 meters per turn+5 meters for each victory point. The duration may be extended by 10 turns for each additional Wyrd point spent. Unlike other powers, the character can elect to spend this point anytime after the activation roll." },
  { n: "Demolishing Hand", path: "FarHand", lvl: 8, roll: "Extrovert + Focus", wyrd: "1", rng: "Sight", dur: "Instant",
    d: "The psychic compresses a field of energy at a point on or near the target’s body and explodes it, like coiling a spring and suddenly releasing it. The damage is equal to Wits+victory points. This is stun damage, like from a Stunner Gun, and ignores energy shields. If the target takes ANY damage (after figuring armor points), he must roll Endurance+Vigor. A failure means he is stunned that turn and the next; on a critical failure, he falls unconscious. If the damage taken is greater than the target’s Endurance, a failure means the target is knocked unconscious. Stun damage heals completely…" },
  { n: "AirDance", path: "FarHand", lvl: 9, roll: "Extrovert + Focus", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic can focus the forces of AirStride upon others, levitating a number of people equal to his Wits rating, and, with an additional Wyrd expenditure, send them in as many separate directions as his victory points (otherwise they will all move in a single direction as a fixed group). Unwilling targets may resist this power with a Dexterity+Dodge roll. The duration may be extended as with AirStride. Omen The Omen path seeks to expand normal time-bound human awareness to include perceptions of the past and possible futures, known in the Phavian Institute as Postcognition and…" },
  { n: "Shadows Gone By", path: "Omen", lvl: 6, roll: "Calm + Observe", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "Past Resonance allows the psychic to see, hear and feel what has happened in the past around a particular object. For instance, a knife used in a killing can be “read” to get a vision of the murderer, as well as the room where it took place, etc. Multiple items may not be selected. The psychic chooses the time period, but it can be accompanied with a request for a particular event (“Who used this knife to kill the marquis?”). How far she can see into the past depends on her successes: one year per success or centuries with a critical success. The psychic can see a past period of about 10…" },
  { n: "Shadows to Come", path: "Omen", lvl: 7, roll: "Calm + Observe", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "Future Resonance allows the psychic to see, hear and feel what will happen in the future around a particular object, place or person (the room a person will be in, who will be with them, etc.). These are shadows of the future, not what WILL happen. Multiple items may not be selected. The psychic chooses the time period, but it can be accompanied with a request for a particular event (“Where will the duke hold his birthday ball?”). How far she can see into the future depends on her successes: one month per success or years with a critical success. The psychic can see a future period of…" },
  { n: "Voice from the Past", path: "Omen", lvl: 8, roll: "Wits + Focus", wyrd: "1", rng: "NA", dur: "Prolonged",
    d: "The psychic can channel the personality of someone who is dead. As in the film Rashomon, these ghosts of the past can sometimes be accepted as witnesses in certain murder trials. Ancient or alien personages may require a scholar on hand to overcome barriers posed by dead or unfamiliar languages. The ghost will speak through the psychic long enough to give her tale (gamemaster’s discretion). The Church claims that these are not departed people but figments of the psychic’s twisted mind or demons parading as dead loved ones, but most people in the Known Worlds believe in ghosts anyway." },
  { n: "Oracle", path: "Omen", lvl: 9, roll: "Calm + Focus", wyrd: "1", rng: "NA", dur: "NA",
    d: "The psychic can foretell the future with accuracy—but cryptically. The psychic goes into a trance and says things which must then be interpreted (i.e., he speaks of events to come in metaphors, abstractions, or inconclusive sentence fragments). The gamemaster is the “voice” for these omens, and he should use this power to reveal the possible future for the characters in his drama. For example, a psychic player character uses Oracle to try to ascertain whether one of the other player characters will be heir to a Hawkwood barony on Leminkainen. The gamemaster knows that there is a rival who…" },
  { n: "Intuit", path: "Psyche", lvl: 1, roll: "Extrovert + Empathy", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic can read another’s surface emotional state, whether she is angry or sad, happy or confused. Emotions are read directly from the target’s mind, as opposed to aura reading, which can be subject to misinterpretation." },
  { n: "Emote", path: "Psyche", lvl: 2, roll: "Passion + Charm or Impress", wyrd: "1", rng: "Sight", dur: "Instant",
    d: "The psychic can project emotions to another, to let them know how he feels (although he can fake emotions by rolling Passion+Knavery instead). The target simply senses the emotion but does not have to react in any particular way to it. The target of this power will know whose emotions he is sensing, although he may not know that his intuition is caused by a psychic power." },
  { n: "MindSight", path: "Psyche", lvl: 3, roll: "Extrovert + Observe", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "MindSight allows the psychic to read another’s surface thoughts. Note that surface thoughts are only what is occupying the target’s attention at that moment, and rarely involve long-range plans, habitual behavior or detailed recollections. Language barriers can get in the way, as can differences in the psychology of alien races from beyond the Known Worlds. A level 5 version of this power, MindSearch, allows the psychic to delve deeper, into the target’s deepest thoughts and memories. The number of victory points should act as a guideline as to how deep or private are the memories which…" },
  { n: "MindSpeech", path: "Psyche", lvl: 4, roll: "Extrovert + Charm", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic is able to project her thoughts into the mind of another. The psychic can choose to hide the source of these thoughts, but the target may become aware that something is happening if a thought seems too strange or unfamiliar to him. As with MindSight, language can be a barrier." },
  { n: "Heart’s Command", path: "Psyche", lvl: 5, roll: "Extrovert + Impress", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic can actually telepathically control another’s emotions. Language is not a factor here, but differences in alien psychology can pose a problem, as is illustrated by the story of the psychic who, in attempting to ingratiate himself to a feral Vorox, accidentally triggered the predator’s violent mating behavior." },
  { n: "HeadShackle", path: "Psyche", lvl: 6, roll: "Extrovert + Charm or Impress", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic gains the ability to telepathically dominate the minds of others. Detailed commands may be projected, which the target will carry out to the best of her ability, but only as long as this power is actively used upon her (this requires one action per turn). Once again, language can be an obstacle." },
  { n: "BrainBlast", path: "Psyche", lvl: 7, roll: "Passion + Impress", wyrd: "1", rng: "Sight", dur: "Prolonged",
    d: "BrainBlast instantly overloads all pain receptor sites in the target’s brain, effectively “wounding” him without inflicting any physical injury. For each victory point on the psychic’s roll, the target suffers a –1 wound penalty as if actually wounded (the Vitality rating itself is not affected); note that the penalty affects ALL rolls the target may make, and this lasts for the rest of the span." },
  { n: "Sympaticus", path: "Psyche", lvl: 8, roll: "Extrovert + Empathy", wyrd: "1", rng: "Sensory", dur: "Prolonged",
    d: "The psychic can easily communicate with, or feel the emotions of, bonded targets, allowing the formation of a telepathic network among non-psychic characters (all information must flow through the psychic using this power, i.e., non-psychic targets may not communicate directly, except through normal channels). However, use of Sympaticus actually makes it harder to manipulate or control these targets (–4 on all rolls to do so)." },
  { n: "Puppetry", path: "Psyche", lvl: 9, roll: "Ego + Focus", wyrd: "1", rng: "Touch", dur: "Prolonged",
    d: "The psychic can telepathically project her will upon a target, dominating them completely and possessing them body and soul. The psychic’s own body must remain inactive during the possession, but the gamemaster may allow actions to be taken with an additional expenditure of Wyrd points (one per action). Sixth Sense Known in the old Phavian Institute as Extra-Sensory Perception, this path seeks to cultivate modes of perception which are considered to be inherent in all sentient beings, but which are seldom or never consciously accessed." },
  { n: "Sensitivity", path: "Sixth Sense", lvl: 1, roll: "Perception + Observe", wyrd: "1", rng: "Sensory", dur: "Prolonged",
    d: "This power improves the physical senses, allowing the character to see in darker situations (but it does not confer IR or UV vision—he still cannot see in total darkness), hear better, and even smell or taste drugs or poisons in food and drink (at the gamemaster’s discretion). If successful, the character gains +3 to his Perception. This bonus can help offset any negative Perception modifiers due to adverse conditions or darkness (see the Perception Modifiers in Chapter Six: Combat, p.165)." },
  { n: "Darksense", path: "Sixth Sense", lvl: 2, roll: "Wits + Observe", wyrd: "1", rng: "Sensory", dur: "Prolonged",
    d: "Darksense allows the character to perceive when there is no light or when she is somehow blinded. She suffers none of the usual negative Perception modifiers for darkness and can use her Sixth Sense powers in the dark. Darksense manifests in a variety of ways, including sonar-like acuity of hearing, tactile hypersensitivity to ground vibrations or minute air currents, and using the character’s own biomagnetic field as a kind of radar. Printed words or pictures may not be seen with Darksense." },
  { n: "Subtle Sight", path: "Sixth Sense", lvl: 3, roll: "Extrovert + Observe", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The character can perceive the psychic auras of others. Auras can reveal general emotions and states of mind, whether someone is human or alien, and if he/she has psychic powers. Auras cannot reveal specific thoughts, although a very successful roll can supply quite a lot of useful information about the target; colors correspond to emotions, movement of the aura indicates general state of mind, and shapes within the aura can show what types of thoughts the target is thinking. See the Auras Chart." },
  { n: "Premonition", path: "Sixth Sense", lvl: 4, roll: "Extrovert + Observe", wyrd: "1", rng: "Sensory", dur: "Temporary",
    d: "Auras Chart General Types of Auras Race/Condition Aura Type Human Simple elongated ovals Ur-Obun Exaggerated egg-shapes, with the big end at the top Ur-Ukar Exaggerated egg-shapes, with the big end at the bottom Vorox Torn, raggedy edges Vau Sleek wedges, pointed at the head Symbiot Tiny filament-threads stretching out to infinity (which cannot be detected without a critical success) The Changed Folded or crimped around the altered body part Unconscious Pale, empty aura Asleep Pale, empty aura, with all color and activity concentrated in the center Psychic/Theurge Deeper, more…" },
  { n: "FarSight", path: "Sixth Sense", lvl: 5, roll: "Extrovert + Observe", wyrd: "1", rng: "Distance", dur: "Prolonged",
    d: "Occasionally known by the old Phavian designation, “clairvoyance,” FarSight allows the psychic to see a distant place. The goal roll to activate FarSight is modified according to the familiarity of the target location: Easy (+4)—The psychic’s own home. Natural (+2)—The psychic’s home town or neighborhood, her regular haunts, etc.. Standard—A place with which the psychic is personally familiar, i.e., anywhere he has been to and can consciously remember. Hard (–2)—An unfamiliar place which the psychic knows about, e.g., famous public places on Byzantium Secundus or Holy Terra, or somewhere…" },
  { n: "FarSound", path: "Sixth Sense", lvl: 6, roll: "Extrovert + Observe", wyrd: "1", rng: "Distance", dur: "Prolonged",
    d: "Occasionally known by the old Phavian designation, “clairaudience,” FarSound allows the psychic to hear a distant place. The same modifiers for FarSight apply. (The Ur-Ukar supposedly have an additional power at this level: FarTouch.)" },
  { n: "Shared Sense", path: "Sixth Sense", lvl: 7, roll: "Extrovert + Empathy", wyrd: "1", rng: "Distance", dur: "Prolonged",
    d: "This power opens a direct sensory conduit from a bonded target to the psychic, who can then see what the target sees, hear what he hears, and so on. Shared Sense allows the psychic to use her powers from a bonded target’s perspective, treating the target’s touch, sight and sensory ranges as her own. In other words, she can sense danger to the target with Premonitions, see from the target’s eyes with Subtle Sight, etc.." },
  { n: "Wyrd Sight", path: "Sixth Sense", lvl: 8, roll: "Introvert + Observe", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic can perceive normally invisible occult activity, such as theurgy rites, psychic powers, occult artifacts, etc.. This can be considered an extremely refined form of Subtle Sight, revealing things which do not register at the lower level. For instance, the aura of a psychic shows a brilliant scintillating white light in the forehead; a beam extending from this light to another person can indicate a telepathic connection or Shared Sense. Most theurgic activity appears to be enveloped in a large unflickering candle-flame, the top point of which stretches up to infinity. Wyrd Sight…" },
  { n: "Senses Shock", path: "Sixth Sense", lvl: 9, roll: "Extrovert + Impress", wyrd: "1", rng: "Touch", dur: "Instant",
    d: "With Senses Shock the psychic can break down his target’s natural adjustment of the intensity of sensory input, overloading the target’s senses: mild light becomes blinding, whispers are screams, a massage becomes a pummeling, and so on. If activation is successful, the target is stunned and incapacitated for one turn per victory point on the activation roll (perhaps more if she is subjected to bright lights, loud sounds, a pummeling, etc.). If the target was a psychic using a Sixth Sense power, she may roll Introvert+Stoic Mind to resist being stunned. Soma The path of Soma (also called…" },
  { n: "Toughening", path: "Soma", lvl: 1, roll: "Introvert + Vigor", wyrd: "1", rng: "Self", dur: "Temporary",
    d: "While this power is activated, the psychic may add 2 to his Endurance rating, plus another 1 per victory point. This does not add to Vitality, only Endurance." },
  { n: "Strengthening", path: "Soma", lvl: 2, roll: "Passion + Vigor", wyrd: "1", rng: "Self", dur: "Prolonged",
    d: "While this power is activated, the psychic may add 2 to her Strength rating, plus another 1 per victory point." },
  { n: "Quickening", path: "Soma", lvl: 3, roll: "Calm + Vigor", wyrd: "1", rng: "Self", dur: "Prolonged",
    d: "While this power is activated, the psychic may add 2 to his Dexterity rating, plus another 1 per victory point." },
  { n: "Hardening", path: "Soma", lvl: 4, roll: "Introvert + Stoic Body", wyrd: "1", rng: "Self", dur: "Prolonged",
    d: "This power actually hardens the skin to a steely consistency, providing an armor rating of 3+1d per victory point against hand-to-hand, melee and conventional firearm attacks, and 1 +1d per victory point against energy weapons. There is no Dexterity or Vigor penalty." },
  { n: "Sizing", path: "Soma", lvl: 5, roll: "Extrovert + Vigor", wyrd: "1", rng: "Self", dur: "Prolonged",
    d: "With Sizing, the psychic may physically become shorter or taller, broader or thinner. This does not affect physical characteristic ratings. The amount by which size may be changed is based on the psychic’s victory points for the activation roll: Victory Height Height Weight Weight Points Increase Decrease Increase Decrease 1 +10% –10% +20% –10% 2 +20% –20% +40% –20% 3 +30% –30% +60% –30% 4 +40% –40% +75% –40% 5 +45% –45% +90% –45% 6 +50% –50% +100% –50%" },
  { n: "Masking", path: "Soma", lvl: 6, roll: "Extrovert + Charm", wyrd: "1", rng: "Self", dur: "Prolonged",
    d: "At this level, the psychic may physically change her facial features (bone structure, eye color, skin color and texture, hair length and color). One feature may be changed with CHAPTER FIVE: OCCULT 139 139 each victory point. With complementary rolls in Disguise and Acting, the psychic can mimic others." },
  { n: "Recovering", path: "Soma", lvl: 7, roll: "Introvert + Remedy", wyrd: "1", rng: "Self", dur: "Instant",
    d: "With this power, the psychic can regenerate one Vitality level per victory point." },
  { n: "Slowing", path: "Soma", lvl: 8, roll: "Calm + Vigor", wyrd: "1", rng: "Self", dur: "Prolonged",
    d: "At this level, the psychic can slow down his bodily operations to an almost undetectable rate, feigning death and reducing his need for oxygen. The duration of this power can be increased at a cost of 1 Wyrd point per additional span." },
  { n: "Closing", path: "Soma", lvl: 9, roll: "Introvert + Vigor", wyrd: "1", rng: "Self", dur: "Prolonged",
    d: "Closing renders the psychic immune to adverse environmental effects, such as airborne drugs and toxins, conventional diseases, extreme weather, etc.. Closing does not render one immune to heat or cold in excess of freezing or boiling temperatures, corrosive atmospheres, explosive decompression or Symbiot invasion. Sympathy This path was little known to the Phavian Institute, perhaps because research on psychic groups was rare, as most psychics tended to work alone. With the rise of the psychic covens of the Dark Ages—a response to the Church’s ban on psychic powers—this path became…" },
  { n: "Bonding", path: "Sympathy", lvl: 3, roll: "Extrovert + Empathy", wyrd: "varies", rng: "Touch", dur: "Perpetual",
    d: "A character can psychically bond with another person(s). This makes it easier to use psychic powers on that person later. The target of the bond must be willing, although he may be scared into accepting the bond (Impress) or fooled into it (Charm or Knavery). He may also be psychically forced to do so. It costs the psychic a number of Wyrd points equal to the target’s Ego or Faith (whichever is higher) to bond him, and a full span must be spent in meditation (the target does not have to meditate, but he must be present during the meditation). When using powers against Bonded targets, the…" },
  { n: "Sanctum", path: "Sympathy", lvl: 4, roll: "Calm + Focus", wyrd: "3", rng: "Sight", dur: "Perpetual",
    d: "The psychic may attune himself to a particular place so that his powers may be used easier in connection with that place. While the place may be anywhere (it does not Resolving Urge and Hubris Conflicts Psi/Urge and Theurgy/Hubris are unique resisted traits. Psi and Theurgy will come into conflict when a character tries to raise one trait past the level of his Urge or Hubris. For example, Eusebius has Psi 5 and an Urge 5 and wants to raise his Psi to 6; he must first tame a level of Urge. Because the two traits have come into direct conflict, the character can choose to enter a combat of…" },
  { n: "Totem", path: "Sympathy", lvl: 5, roll: "Wits + relevant Skill", wyrd: "varies", rng: "Touch", dur: "Perpetual",
    d: "The character can create a bond with an item, allowing him to use his powers easier in association with that item. Wyrd costs are one less, and all tasks are considered Natural (+2)—although this does not allow him to more easily use the item itself; a think machine may be just as baffling before a Totem Bond as after. In addition, the character gains such an affinity with the item that he always knows where it is anywhere within his sensory range. This does not confer any form of FarSight, it is simply a sense of the item’s location. Wyrd points may be spent to extend this range for one…" },
  { n: "Coven Brand", path: "Sympathy", lvl: 6, roll: "Ego + Impress", wyrd: "varies", rng: "Touch", dur: "Perpetual",
    d: "A particular psychic is declared anathema, and has a sort of anti-bond placed upon him whereby it is harder for him to use his own powers against the psychic. This is usually performed by members of a psychic coven upon an outcast from their coven, to prevent him from easily working against them at a later date. This is mainly used by the Favyana rather CHAPTER FIVE: OCCULT 141 141 than the Invisible Path, who punish most extreme transgressions against them with death instead of exile. It is only effective between the user of this power and the recipient. This is cast just like Bonding…" },
  { n: "Mojo Bond", path: "Sympathy", lvl: 7, roll: "Extrovert + Impress", wyrd: "1", rng: "Sight", dur: "Temporary",
    d: "The psychic can form a bond with another person over a distance and against his will. To do so, he must have a sympathetic focus, an item that bears the target’s psychic resonance, such as a well-worn item of his clothing, a lock of hair, fingernail clippings, etc. These items must have a relatively fresh connection to the target, having been on him within the past month. The psychic does not need to meditate or spend more than 1 Wyrd point, but the duration of the Mojo Bond may not be extended—he has 10 turns in which to gain his advantage. Once successfully used, this power may not be…" },
  { n: "Sever Bond", path: "Sympathy", lvl: 8, roll: "Ego + Impress", wyrd: "2", rng: "Touch", dur: "Instant",
    d: "The psychic can sever any type of bond between two psychics (including a Mojo Bond or a Coven Bond, below). The severing is permanent, although new bonds may be formed again using the same powers. Wyrd points may be spent to increase the targets if more than two people share the bond." },
  { n: "Coven Bond", path: "Sympathy", lvl: 9, roll: "Extrovert + Empathy", wyrd: "varies", rng: "Sight", dur: "Temporary",
    d: "Two or more psychics who share a Bond (level 3) can merge their psyches into greater sympathy, allowing them to place Wyrd points into a collective pool from which any of them can draw upon at will for the duration of the span. The amount of Wyrd spent at activation by each of the participants is the amount of the collective Wyrd pool; a psychic’s Psi rating determines the maximum amount of Wyrd he may contribute. This pool exists for only one span, after which it disappears; the participants do not get any unspent Wyrd points back. While only one of the participants activates this power,…" },
  { n: "Vis Eye", path: "Vis Craft", lvl: 1, roll: "Perception + Focus", wyrd: "1", rng: "SIght", dur: "Temporary",
    d: "The psychic can sense the use of energy around him (a foe’s active energy shield, a laser sight trained on the psychic, a spy camera filming him) and discern the type of energy (electrical, fusion) and trace its source (although this may require a sustained roll if the source is well-hidden). A level 3 version of this power allows the psychic to sense and discern spiritual energies, such as Wyrd, Symbiot Lifeforce or even the strange energy used by Anunnaki tech." },
  { n: "Vis Drain", path: "Vis Craft", lvl: 2, roll: "Passion + Volt Redemption", wyrd: "1", rng: "Touch", dur: "Temporary",
    d: "The psychic can drain or cut off the flow of the power to or from various items, such as fusion cells or a building’s power grid (this power is not transferred anywhere useful unless the character also uses the Vis Flow power, below). The amount of Wyrd points spent determines how much power can be drained from a source. The psychic can spend Wyrd to increase the duration to prolonged. Wyrd Power (equivalents) 1 (base) 1 fusion cell 2 10 fusion cells; enough energy to power a small room or skimmer 3 Enough energy to power a building or flitter 4 Enough energy to power a city block or…" },
  { n: "Vis Flow", path: "Vis Craft", lvl: 3, roll: "Passion + Volt Redemption", wyrd: "1", rng: "Touch", dur: "Instant",
    d: "The psychic can channel incoming energy to charge fusion cells, flashlights or starship engines. He must touch the item to be charged and the source of energy (a sparking live wire, a fusion charging plug, a Symbiot giving its Lifeforce). Mild shocks will not harm the psychic while this power is active, but he is not immune to energy attacks or severe power surges. It is possible to use this power when being attacked by lasers, blasters or higher levels of Vis Craft, but regardless of success on channeling the energy, the psychic will suffer any damage normally. (If an energy shield is…" },
  { n: "Vis Shock", path: "Vis Craft", lvl: 4, roll: "Dexterity + Fight or Melee", wyrd: "1", rng: "Touch (see text)", dur: "Instant",
    d: "The psychic can transform her own bioelectrical field into a high voltage discharge with a hand-to-hand or melee attack. This normally adds four dice to any damage roll. However, a character can also attempt to slowly slip under shields and hit the target once his fist or weapon is past the shield (suffer –2 to Initiative, withhold victory dice and hope the damage does not exceed the shield’s impact threshold). Once the blow contacts a surface, the psychic can release the charge (four dice, ignore energy shields but not other armor). The range on this power may not be increased. CHAPTER…" },
  { n: "Vis Shield", path: "Vis Craft", lvl: 5, roll: "Endurance + Stoic Body", wyrd: "1", rng: "Self", dur: "special (see text)",
    d: "The psychic may use his own bioelectrical energy to erect a personal energy shield around himself. This acts similar a standard energy shield; it allows 10 hits per power activation and the protection rating is 5/10. In addition, the field fluctuates at need, so the character can wear any form of armor he desires without compromising the field. Note that this field does not interfere with the Vis Flow power (above); attacks absorbed by this power can be transferred elsewhere." },
  { n: "Vis Bolt", path: "Vis Craft", lvl: 6, roll: "Dexterity + Shoot", wyrd: "1", rng: "Self", dur: "Instant",
    d: "The psychic can project energy at a target from a distance. The damage is equal to Endurance plus victory dice, plus one die for each extra Wyrd point spent (max =Psi rating). In addition, this damage can bleed through energy shields on damage dice results of 1 or 2." },
  { n: "Vis Vortex", path: "Vis Craft", lvl: 7, roll: "Endurance + Vigor", wyrd: "1", rng: "Touch", dur: "Instant",
    d: "The psychic can generate power, which he can use to recharge fusion cells, power skimmers, etc. Use the chart given with the Vis Drain power, above, to determine the Wyrd point costs per power generated. The maximum amount of points the psychic may spend on Wyrd to generate power is equal to his Psi rating. The range and duration of this power may be increased normally." },
  { n: "Vis Storm", path: "Vis Craft", lvl: 8, roll: "Passion + Vigor", wyrd: "1", rng: "Sight", dur: "Instant",
    d: "The psychic can unleash an energy surge on an area from a distance. The base radius from the shock point is 10 meters, and anyone standing within this radius is affected. The radius may be increased by 5 meters per extra Wyrd point spent. The damage is equal to Endurance plus victory dice, plus one die for each extra Wyrd point spent (max = Psi rating). In addition, this damage can bleed through energy shields on damage dice results of 1 or 2." },
  { n: "Primal Vis", path: "Vis Craft", lvl: 9, roll: "Passion + Focus", wyrd: "NA", rng: "Sight", dur: "Instant",
    d: "The psychic can tap into an invisible, universal spiritual power grid to replenish and/or add to his Wyrd points. This power may be used only once per span, but it can generate an amount of Wyrd equal to 1 plus the victory points gained on the activation roll. In times of dire need, however, the psychic may call on his Urge for aid: he gains an extra amount that span equal to his Urge rating. The psychic must roll to resist its awakening (Ego+Stoic Mind); failure means that the Urge is awake. Even if the psychic had no levels in Urge, he may elect to take one level to gain the Wyrd.…" },
];

/** Theurgic rites, by sect (p.147–p.160). */
export const THEURGIC_RITES = [
  { n: "The Prophet’s Holy Blessing", sect: "Common to All Sects", lvl: 1, roll: "Faith + Focus", wyrd: "1", comp: "G", rng: "Touch", dur: "special (see text)",
    d: "By tracing the Church’s symbol on a companion’s forehead or in her general direction, a theurge may aid the target in a particular task, adding the victory points to the target’s goal roll. The effect lasts until the target has made the roll for the particular task blessed. (If the rite is successful, the character will receive a minimum of at least one victory die, regardless of the number of successes rolled.)" },
  { n: "The Devotional Liturgy", sect: "Common to All Sects", lvl: 2, roll: "Extrovert + Oratory", wyrd: "1", comp: "L", rng: "Sensory", dur: "Prolonged",
    d: "Recitation of this passage from the Omega Gospels is the traditional way of boosting morale, usually before battle. The liturgy takes about fifteen minutes to read, and all true believers within earshot add the theurge’s victory points to all rolls involving Faith or Calm for the next span. (The range of this effect is not extended by PA systems or long-distance communications.) Characters under the effect of the Liturgy may not Incite Passion or employ Steady Hand." },
  { n: "The Laying On of Hands", sect: "Common to All Sects", lvl: 3, roll: "Calm + Remedy", wyrd: "1", comp: "P", rng: "Touch", dur: "Instant",
    d: "By calling upon Amalthea, Patron Saint of healing and compassion, disciple of the Prophet, the theurge may bring comfort to his injured comrades by touching their wounds. Each victory point heals one wound level." },
  { n: "The Prophet’s Censure", sect: "Common to All Sects", lvl: 4, roll: "Passion + Focus", wyrd: "1", comp: "L, G", rng: "Sight", dur: "Special (see text)",
    d: "The theurge may give an enemy of the faith a small taste of divine displeasure by repeating the first two lines of the Prophet’s Admonishment of the Unbelievers and making the sign of the barred jumpgate in the target’s direction. The reverse of the Holy Blessing, Censure penalizes the target in a particular task, subtracting the theurge’s victory points from the target’s goal roll. The effect lasts until the target has made the roll for the particular task censured." },
  { n: "The Pulpit’s Gift", sect: "Common to All Sects", lvl: 4, roll: "Passion + Oratory", wyrd: "1", comp: "L, G", rng: "Sensory", dur: "One Act",
    d: "Developed mainly for use by missionaries on new worlds, this rite increases the social influence of a theurge upon the people to whom she preaches. For the rest of the act, the theurge may add her victory points from this rite to any Charm or Impress rolls directed at a member of her new “flock.”" },
  { n: "Oath to the Saints", sect: "Common to All Sects", lvl: 5, roll: "Faith + Oratory", wyrd: "1 per person", comp: "L, G, P", rng: "Sight", dur: "Perpetual",
    d: "Inspired by the Oath of Fellowship pledged by Zebulon’s eight disciples to one another in their time of worst trial, this rite allows a party to pledge themselves to each other under the patronage of a saint. This rite must be cast by an ordained priest not of the party (a witness before the Pancreator), although any theurges within the party may assist in the rite (see Group Rites, p.156). This is similar to the psychic power of Bonding, for it allows all members of the party bonuses when casting theurgy upon one another (+2 goal roll). The particular saint whose name is invoked lends…" },
  { n: "The Tongues of Babel", sect: "Common to All Sects", lvl: 6, roll: "Wits + Empathy", wyrd: "1", comp: "G, P", rng: "Self", dur: "Prolonged",
    d: "Also common among missionaries, the Tongues of Babel enables a theurge to understand and speak almost any language he does not already understand. For some time before the rite, he must hear the language spoken frequently by natives or other fluent speakers. The victory points for this roll provide bonuses for any roll involved in communicating in that language during that span, whether it be orating before a crowd or reading a moving sermon. This rite does not confer the ability to read the language, unless it is normally written (or happens to be spelled out phonetically) in the Urthish…" },
  { n: "The Righteous Assignation of Penance", sect: "Common to All Sects", lvl: 7, roll: "Faith + Empathy", wyrd: "1", comp: "L, P", rng: "Special (see text)", dur: "Special (see text)",
    d: "This rite is central to the Church’s function in the Known Worlds, since this is how humanity learns, through confession, to make good its sins. In most cases, of course, the rite is no more than a ceremonial formality, but when the sins in question are of overwhelming enormity, or have occult implications beyond simple personal salvation, theurgic Assignation can prove to be the only way of navigating these dark mysteries. The effect of the Righteous Assignation is primarily concerned with roleplaying rather than rules; most penances tend to be charitable donations, community or personal…" },
  { n: "Sanctification", sect: "Common to All Sects", lvl: 7, roll: "Faith + Focus", wyrd: "2", comp: "G, P", rng: "Touch", dur: "Perpetual",
    d: "The theurge sanctifies an object, turning it into a Vestment (see above). While this rite does not provide the occult protections that the level 1 Orthodoxy rite of Consecration does, it is permanent. Although vestment’s may lose their sanctity over time and neglect, as long as they are wellcared for, they will continue to add bonuses to a theurge’s rites. This rite may be cast a number of times per week equal to the theurge’s Theurgy rating; it is not intended to allow priests to run vestment factories. A 8th level version of this rite allows the theurge to create an Article of Faith; its…" },
  { n: "Shield of Faith", sect: "Common to All Sects", lvl: 8, roll: "Extrovert + Focus", wyrd: "1 (see text)", comp: "G, P", rng: "Self", dur: "Special (see text)",
    d: "Similar to the technological energy shield, this rite creates a hemispherical field with a three meter radius around the theurge, and moves as she moves. The Shield lasts for the rest of the span, and the radius can be extended with additional Wyrd points at a rate of one meter per point spent. The maximum armor rating for the Shield of Faith is 15 plus the theurge’s victory points; the minimum amount of damage which will activate the Shield is the theurge’s Hubris rating. (If she has no Hubris, then 1 point is the minimum.) The Shield can take a number of hits (see Energy Shields in…" },
  { n: "Providential Deliverance", sect: "Common to All Sects", lvl: 9, roll: "Faith + Focus", wyrd: "1", comp: "L, G, P", rng: "Self", dur: "Special (see text)",
    d: "This rite enables a theurge in an extremely dangerous situation to escape in some unlikely manner that may even border on the miraculous. A successful casting of Deliverance means that the gamemaster must orchestrate events in such a way as to allow the caster to make a clean getaway from the peril in which he finds himself. This does not mean that the impossible can happen, only the highly improbable; Deliverance can take such forms as a unknown assailant attacking someone who is about to kill the theurge, or a captor accidentally dropping his keys while visiting the theurge’s dungeon…" },
  { n: "Consecration", sect: "Orthodox Rituals", lvl: 1, roll: "Faith + Focus", wyrd: "1", comp: "G, P", rng: "Touch", dur: "One Act",
    d: "Consecration purifies an item from evil taint, effectively making a vestment out of it for the duration of one act. (After that act, the item returns to normal, unless a critical success was rolled, in which case the Consecration is permanent.) The Consecrated item resists being affected by psychic powers, Antinomy, Urge or Hubris; half of the casting victory points (rounded up) become a negative penalty for any of these powers attempting to target the item. Items of Tech Level 5+ are hard to consecrate; subtract one from the casting roll." },
  { n: "Light", sect: "Orthodox Rituals", lvl: 2, roll: "Passion + Focus", wyrd: "1 (see text)", comp: "G", rng: "Self", dur: "Prolonged",
    d: "This rite creates a glowing insubstantial sphere in the theurge’s palm capable of casting enough light to read by in a three-meter radius. This radius is extended by one meter per victory point (at caster’s choice). An alternate version of this rite creates a tight searchlight-type beam which extends from the theurge’s palm, which can be used to search darkened rooms or blind enemies of the Faith. The range for this beam is 10 meters plus two meters per victory point." },
  { n: "Armor of the Pancreator", sect: "Orthodox Rituals", lvl: 3, roll: "Faith + Dodge", wyrd: "1", comp: "L, G", rng: "Touch", dur: "Prolonged",
    d: "A more exact equivalent of the energy shield, this theurgic force field protects the target by conforming itself to the target’s body. Unlike Shield of Faith, the Armor of the Pancreator does not need to be centered on the theurge herself, but can be projected around another person. (The target must be declared when this rite is cast, and cannot be transferred to anyone else.) The Armor lasts for one span. The maximum armor rating for the Armor of the Pancreator is 10 plus the theurge’s victory points; the minimum damage which will activate the Armor is the theurge’s Hubris rating. (If she…" },
  { n: "Faithful Heart", sect: "Orthodox Rituals", lvl: 4, roll: "Introvert + Stoic Mind", wyrd: "1", comp: "L, P", rng: "Sight", dur: "Prolonged",
    d: "This rite shields the soul and mind of a true believer against mental invasion or domination by psychics and their Urges, theurgists, alien telepaths or Antinomists. It can be cast by the theurge upon himself or another. The victory points for casting become a negative penalty on all mental attacks directed at the target." },
  { n: "Dispersal of Darkness", sect: "Orthodox Rituals", lvl: 5, roll: "Passion + Impress", wyrd: "1", comp: "L, G", rng: "Special (see text)", dur: "Temporary",
    d: "The theurge may act as a kind of physical repulsion field against certain servitors of evil, such as the husks of the dead (see Chapter Eight: Gamemastering, p.255), the Doppelgangers of psychics, those under malicious influence from a negative Ur-artifact, etc.. The number of successes represents the closest distance in meters to which an evil minion can approach the theurge. The duration may be extended by 10 turns for each extra Wyrd point spent (these points can be spent any time after activation). CHAPTER FIVE: OCCULT 151 151" },
  { n: "Consecration of Land", sect: "Orthodox Rituals", lvl: 6, roll: "Faith + Focus", wyrd: "1", comp: "G, P", rng: "Special (see text)", dur: "One Act",
    d: "Usually a prerequisite when building a temple, this rite acts as the single-item Consecration above, but is applied to an area equal to the theurge’s Extrovert rating ×10 in square meters. Consecrated ground is impassable to the walking dead, and occult powers originating from unpenitent psychics, Antinomists or negative Ur-artifacts receive a penalty equal to the victory points from casting the Consecration. Note that this does not only apply to powers being used from within the Consecrated area, but also when the area is targeted from without. For example, an unpenitent psychic on the…" },
  { n: "Blessing the Crops", sect: "Orthodox Rituals", lvl: 7, roll: "Extrovert + Survival", wyrd: "1", comp: "L, G, P", rng: "Special (see text)", dur: "Perpetual",
    d: "Growing from the traditional role of the priesthood in agrarian cultures, this rite enables a theurge to purify or enrich an amount of food equal to his Theurgy rating in kilograms. Crop Blessing will neutralize impurities and organic poisons, restore perishable foods within two days of their having spoiled, and, in the case of untainted foodstuffs, make them more nutritious and fulfilling by 50% (e.g.: a ten day supply of rations can be stretched out to fifteen days). This rite is very valuable on many worlds, where the fading suns fail to nourish crops." },
  { n: "Exorcism", sect: "Orthodox Rituals", lvl: 8, roll: "Faith + Impress", wyrd: "1", comp: "L, G, P", rng: "Sensory", dur: "Perpetual",
    d: "With this rite a theurge can drive out any dark power which is influencing or possessing the target (usually psychic or Antinomic domination and demonic possession, although the influence of Ur-artifacts and certain aliens can also be dispelled in this way). Exorcism can be a long and arduous process. It is a sustained action, and the exorcist needs to accumulate 25 victory points in order to rid the target of whatever is possessing or influencing him. He must spend the Wyrd point cost with every roll. If he runs out of Wyrd before accumulating 25 successes, the exorcism fails, and the…" },
  { n: "Sealing the Temple", sect: "Orthodox Rituals", lvl: 9, roll: "Calm + Impress", wyrd: "1", comp: "L, G, P", rng: "Special (see text)", dur: "Prolonged",
    d: "In times of great trouble, Orthodox priests used this rite to protect their flock (and, in some unfortunate cases, protect themselves from their flock) by turning their temple into a temporary fortress. When ritually sealed in this way, a temple is considered to have a large energy shield surrounding it; the maximum armor rating is 20, the minimum damage which will activate the seal is the caster’s Hubris rating (if he has no Hubris, then 1 point is the minimum), and it can take a number of hits equal to double the caster’s Theurgy rating. (Additional hits can be purchased at a rate of one…" },
  { n: "Soul’s Vessel", sect: "Brother Battle Rituals", lvl: 1, roll: "Passion + Stoic Body", wyrd: "1", comp: "P", rng: "Self", dur: "Prolonged",
    d: "One of the core teachings of Brother Battle is the perfection of the physical body as the instrument of action in the service of the Pancreator. This rite aids the theurge by adding three to the goal number of all non-combat rolls involving physical traits (running, jumping, lifting, etc.). Rightfully Guided Hand" },
  { n: "Armor of the Pancreator", sect: "Brother Battle Rituals", lvl: 3, roll: "Faith + Dodge", wyrd: "1", comp: "L, G", rng: "Self", dur: "Prolonged",
    d: "This rite is identical to the level 3 Orthodoxy rite, above, except that the Brother Battle version can be expanded to include bulkier armor which has been Sanctified or Consecrated." },
  { n: "Righteous Fervor", sect: "Brother Battle Rituals", lvl: 4, roll: "Passion + Vigor", wyrd: "1", comp: "P", rng: "Self", dur: "One Act",
    d: "Brothers Battle monks are renowned for their discipline and loyalty. The Rite of Righteous Fervor intensifies their already legendary stoicism, allowing a Brother to resist all temptations, persuasions, fast talks, etc., that would sway him from his duty. During casting, the Brother declares his duty (“No harm shall come to the bishop under my watch,” or “I shall safely deliver the writ to the Heirophant on Byzantium Secundus.”). If the casting is successful, the Brother is immune to any mental or social obstacles which would hinder his duty (such as the orders of the bishop to step down…" },
  { n: "Liturgy of the Wrathful Host", sect: "Brother Battle Rituals", lvl: 5, roll: "Passion + Charm", wyrd: "1", comp: "L, P", rng: "Sensory", dur: "Prolonged",
    d: "This passage from the Omega Gospels is read to Brothers about to go into combat so that their hearts may be filled with the fire of their holy cause, whatever it may happen to be. For the next span, the victory points from the reading may be added to the goal number of all listeners’ rolls involving Faith or Passion. The Liturgy takes about 10 minutes to read, and the range of this effect is not extended by PA systems or long-distance communications. Characters under the effect of the Liturgy may not Incite Passion or employ Steady Hand." },
  { n: "Smiting Hand", sect: "Brother Battle Rituals", lvl: 6, roll: "Faith + Vigor", wyrd: "1", comp: "L, G", rng: "Self", dur: "Instant",
    d: "Using this rite to channel the force of the Holy Flame through his limbs, a Brother may strike down his foes with righteous power. The victory dice from casting this rite may be added to the Brother’s fist, kick or melee weapon damage—in addition to normal damage from the weapon and the goal roll’s victory dice. (If the rite is successful, the character will receive a minimum of at least one victory die, regardless of the number of successes rolled.)" },
  { n: "Fearsome Majesty", sect: "Brother Battle Rituals", lvl: 7, roll: "Passion + Impress", wyrd: "1", comp: "L, G", rng: "Sight", dur: "Prolonged",
    d: "Casting Multiple Rituals A person can potentially be under the spell of multiple rites per turn. In other words, a Brother Battle could cast upon himself Soul’s Vessel, Armor of the Pancreator, Liturgy of the Wrathful Host and Smiting Hand. However, each rite after the first costs one extra Wyrd point to cast. In addition, casting so many powers upon oneself is vain act; each extra rite increases the chance of gaining Hubris should a casting fail miserably. Every time a theurgist fumbles a theurgy rite casting roll, he must roll Theurgy+Focus or else gain a level of Hubris. Casting…" },
  { n: "Oath of the Shieldmates", sect: "Brother Battle Rituals", lvl: 8, roll: "Extrover + Empathy", wyrd: "1", comp: "L, G, P", rng: "Sensory", dur: "Prolonged",
    d: "Similar to the psychic power Sympaticus (see the Psyche path, p.134), this rite allows a Brother to band his comrades into an elite fighting unit. He can easily communicate with, or feel the emotions of, chosen targets, allowing the formation of a telepathic network among non-theurgic characters (all information must flow through the Brother who cast the rite, i.e., non-theurgic targets may not communicate directly, except through normal channels). However, use of this rite actually makes it harder to manipulate or control these targets (–4 on all rolls to do so). Not just any target can…" },
  { n: "Salutation to Zakhayelos, Lord of Hosts", sect: "Brother Battle Rituals", lvl: 9, roll: "Passion + Impress", wyrd: "1", comp: "L, G, P", rng: "Special (see text)", dur: "Special (see text)",
    d: "This exceptionally rare and powerful rite, a closely guarded secret of the order, enables a theurge to contact and summon to the physical world one of the “bodiless powers of the Empyrean,” the strong and warlike intelligence known as Zakhayelos. According to Eskatonic doctrine, Zakhayelos rules in the Fifth Emanation from the Celestial Sun, among the ranks of the Imperitories. Zakhayelos is the pure embodiment of all the military virtues to which the order aspires: strength, courage, discipline, a perfect understanding of strategy and logistics. As with all of the Empyrean powers,…" },
  { n: "Celestial Alignment", sect: "Eskatonic Order Rituals", lvl: 1, roll: "Perception + Observe", wyrd: "1", comp: "P", rng: "Self", dur: "Perpetual",
    d: "One of the earliest rites developed by Eskatonic theurges was that of Celestial Alignment, which proved useful to explorers on new planets seeking Ur-artifacts or forgotten wisdom. This rite enables a theurge to keep perfect mental notation of all the movements of the surrounding solar system, as well as the constellations (as they appear to an observer on planetside). Thus the theurge, with but a glance at the sky, can reckon sidereal time and track his position, direction and motion as he travels across the planet. The effect of this rite is permanent, but applies only to the planet upon…" },
  { n: "Divine Revelation", sect: "Eskatonic Order Rituals", lvl: 2, roll: "Wits + Focus", wyrd: "1", comp: "P", rng: "Self", dur: "Special (see text)",
    d: "Developed from the common prayer for guidance, this rite guarantees the theurge some kind of significant insight into whatever problem is vexing her. The gamemaster should adjust the degree of insight according to the victory points: one would furnish only the slightest of clues, something which might not even seem important to the player; three provides a more substantial answer that will lead most characters to a solution; five or six will grant the theurge a clear indication to the exact nature of her dilemma and what needs to be done to alleviate it. With a critical success, profound…" },
  { n: "Rending the Veil of Unreason", sect: "Eskatonic Order Rituals", lvl: 3, roll: "Perception + Focus", wyrd: "1", comp: "P", rng: "Sight", dur: "Prolonged",
    d: "This rite grants the theurge the equivalent of the psychic power Subtle Sight, except that the auric image that the theurge actually perceives is based on the Eskatonic conception of the soul. Rending the Veil shows the actual “mirror” reflecting the light of the Celestial Sun, the Holy Flame of the spirit, centered on the heart region within the conventional aura. The size of the reflected Flame indicates the target’s Faith rating; with a Faith of 10, the Flame is large and bright, filling the surface of the “mirror,” while a Faith of 1 shows up as a candle flame seen at the end of a dark…" },
  { n: "Second Sight", sect: "Eskatonic Order Rituals", lvl: 4, roll: "Perception + Focus", wyrd: "1", comp: "P", rng: "Sight", dur: "Prolonged",
    d: "This rite is the theurgic equivalent of the psychic power Wyrd Sight, but with more of an emphasis on the moral forces at work in the targeted viewing area. A theurge casting Second Sight may see a psychic’s Urge, for example, as a dark fetal form in the psychic’s brain (at lower levels) or as a fully formed shadow which moves independently of the psychic casting it. Second Sight reveals the presence of demonic influence, with their dark forms hovering in the air around a Antinomist, or coiled up in the body of someone who is possessed. Second Sight also shows the theurge details of any…" },
  { n: "Osseous Transmutation", sect: "Eskatonic Order Rituals", lvl: 5, roll: "Wits + Alchemy", wyrd: "1", comp: "L, G", rng: "Touch", dur: "Perpetual",
    d: "By calling upon the transformative powers of his own indwelling portion of the Holy Flame, an Eskatonic priest can fossilize any object or body of substance less than or equal to his Theurgy rating times 20 in kilograms. (Additional mass can be bought at 10 kilograms per Wyrd point.) The transmuted object is composed of a gray chalky sandstone-like stuff, which is just strong enough to support a human’s weight but brittle enough to crack or crumble with sharp impact. The effect is permanent. Ur-artifacts are not affected by this rite. Living organic tissue cannot be affected with this…" },
  { n: "All-Seeing Eye", sect: "Eskatonic Order Rituals", lvl: 6, roll: "Perception + Observe", wyrd: "1", comp: "L, P", rng: "Self", dur: "Prolonged",
    d: "The equivalent of the psychic power FarSight, the Rite of the All-Seeing Eye allows the theurge to observe a place in which she is not actually present. Consult the description of FarSight to see how the casting roll should be modified according to the familiarity of the targeted place." },
  { n: "Refinement of Essence", sect: "Eskatonic Order Rituals", lvl: 7, roll: "Wits + Alchemy", wyrd: "1", comp: "L, G", rng: "Touch", dur: "Perpetual",
    d: "A more specialized form of the Rite of Osseous Transmutation, the Rite of Refinement enables the theurge to cast out impurities or non-essential elements from an object or body of substance less than or equal to his Theurgy rating times 20 in kilograms. (Additional mass can be bought at 10 kilograms per Wyrd point.) Refinement may be used to purify fuel, strengthen building materials and detoxify food, water or the atmosphere of an enclosed and sealed space. CHAPTER FIVE: OCCULT 157 157 Unlike Transmutation, Refinement may be used on living beings for beneficial effects, but the same…" },
  { n: "Investiture", sect: "Eskatonic Order Rituals", lvl: 8, roll: "Calm + Focus", wyrd: "1", comp: "L, G, P", rng: "Touch", dur: "Perpetual",
    d: "The Rite of Investiture is used to create a Wyrd Tabernacle (see Relics, p.147) out of a targeted object. The maximum number of Wyrd points which the Invested Tabernacle may store is equal to the number of successes on the casting roll, and may be increased up to a maximum of 20 through repetition of the rite. Note that the Rite of Investiture does not actually bind any Wyrd points into the Tabernacle; this is a separate process involving a Theurgy+Focus roll, as described above under Wyrd Tabernacle. Knowledge and Conversation of" },
  { n: "Tholumiyelos, Lord of Wisdom", sect: "Eskatonic Order Rituals", lvl: 9, roll: "Passion + Impress", wyrd: "1", comp: "L, G, P", rng: "Special (see text)", dur: "Special (see text)",
    d: "This exceptionally rare and powerful rite, a closely guarded secret of the order, enables a theurge to contact and summon to the physical world one of the “bodiless powers of the Empyrean,” the clever and insightful intelligence known as Tholumiyelos. According to Eskatonic doctrine, which describes the Empyrean as being presided over by “luminous sentiences” occupying a hierarchy of concentric Emanations from the Celestial Sun, Tholumiyelos rules in the Eighth Emanation, among the ranks of the Archons. Embodying the Eskatonic virtues of questing for secret lore and the cultivation of…" },
  { n: "Knowing the False Heart", sect: "Temple Avesti Rituals", lvl: 1, roll: "Perception + Empathy", wyrd: "1", comp: "G", rng: "Sight", dur: "Prolonged",
    d: "Essential to the Avestite pursuit of justice, this rite allows the theurge to act as a human lie detector. Since this rite focuses only on intentional dishonesty and deliberate untruthfulness, it is sometimes possible for the target to dissemble, hiding or twisting the truth with a contested roll of Wits or Calm+Charm. This roll can receive a negative modifier if the target is trying to hide a sin of his own, and a positive one if the target is protecting an innocent under suspicion. The Avestite may still detect half-truths with three or more victory points, and may guess their exact…" },
  { n: "Scent of Evil", sect: "Temple Avesti Rituals", lvl: 2, roll: "Perception + Empathy", wyrd: "1", comp: "G, P", rng: "Sensory", dur: "Prolonged",
    d: "Casting Scent of Evil enables a theurge to “sniff out” acts of Antinomy, the actions of a psychic’s Urge and the presence of demons or alien artifacts with a negative influence. This rite only indicates the presence of such evil, but does not show the theurge exactly what is going on; some degree of precision is possible, however, with a more successful roll. One victory point, for example, merely signals evil’s presence in a general area (“There is evil in this house!”); with three, a more specific area can be sensed (“Somebody in this room…”); five or six gives the theurge a sense of the…" },
  { n: "Sting of Conscience", sect: "Temple Avesti Rituals", lvl: 3, roll: "Extrovert + Impress", wyrd: "1", comp: "L, G", rng: "Sight", dur: "Prolonged",
    d: "This rite is usually accompanied by a verbal harangue from the theurge or another Avestite, the two combining to make the target feel incredibly guilty about some past sin or misdeed. If uncontested, the target will feel compelled to confess and make up for the transgression. The target may choose to contest with a roll of Calm+Stoic Mind. When this rite is cast without the verbal accusations to guide it, there is no telling exactly what its effect may be. A relatively guiltless person may begin to obsess on some minor bit of mischief from childhood, while a truly sinful person may be…" },
  { n: "Torchbearing", sect: "Temple Avesti Rituals", lvl: 4, roll: "Passion + Focus", wyrd: "1", comp: "G", rng: "Touch", dur: "Temporary",
    d: "With this rite the theurge can create a flame without using lighters, matches or flint and steel. After the first 10 turns, the fire will need fuel to burn like any other, but it can be kept burning without fuel by spending one Wyrd point for each extra five turns. Normally the flame can only be ignited at touch, but a 6th level version of this rite exists in which the flame can be created anywhere in sight." },
  { n: "Fault of the Soulless", sect: "Temple Avesti Rituals", lvl: 5, roll: "Special (see text)", wyrd: "1", comp: "L, G", rng: "Sight", dur: "Special (see text)",
    d: "Developed soon after the Fall, this rite targets a piece of high-tech and causes it to malfunction. Normally used against personal technology (blasters, comlinks, a single computer terminal, a robot of human size or smaller), this rite can be used to target larger machines with an additional Wyrd expenditure based on size and complexity (e.g., 2 points to disable a personal land vehicle, 5 points for a building’s security system, and 50 points to take out a starship. At the gamemaster’s discretion, this can be adjusted by circumstances; for example, a theurge with sufficient tech knowledge…" },
  { n: "Fearsome Majesty", sect: "Temple Avesti Rituals", lvl: 6, roll: "Passion + Impress", wyrd: "1", comp: "L, G", rng: "Sight", dur: "Prolonged",
    d: "This rite is identical to the level 6 Brother Battle rite of the same name." },
  { n: "Inquisitory Commandment", sect: "Temple Avesti Rituals", lvl: 7, roll: "Passion + Inquiry", wyrd: "1", comp: "L", rng: "Sight", dur: "Temporary",
    d: "Use of this rite is the theurgic version of a shot of truth serum; the target is compelled to answer all questions addressed to her. Questions must be answered fully, comCHAPTER FIVE: OCCULT 159 159 pletely and honestly, without evasion or trickery. If the target chooses to contest the rite, the theurge’s Faith rating is subtracted from the contesting roll (see Defending Against Occult Powers, p.129)." },
  { n: "Tortures of the Damned", sect: "Temple Avesti Rituals", lvl: 8, roll: "Passion + Impress", wyrd: "1", comp: "L, G", rng: "Sight", dur: "Prolonged",
    d: "This rite has basically the same effect as the psychic power BrainBlast, incapacitating the target with unimaginable pain, except that this theurgic version floods the target’s mind with images of Gehenne (hell). These visions may take the form of Orthodox and Avestite description, burning hellfire or numbing cold lasting (or at least seeming to last) for eternity, or may take a more personal form, the reliving of a traumatic event or seeing one’s greatest fears come to pass, or some amalgamation of both. In either case, the target will be a pathetic, sobbing wreck for at least seven turns…" },
  { n: "Petition to Jachemuyelos, Lord of Judgment", sect: "Temple Avesti Rituals", lvl: 9, roll: "Passion + Impress", wyrd: "1", comp: "L, G, P", rng: "Special (see text)", dur: "Special (see text)",
    d: "This exceptionally rare and powerful rite, a closely guarded secret of the sect, enables a theurge to contact and summon to the physical world one of the “bodiless powers of the Empyrean,” the stern but fair arbiter of disputes known as Jachemuyelos. According to Eskatonic doctrine, Jachemuyelos rules in the Fourth Emanation from the Celestial Sun, among the ranks of the Dominions. Odd as it may seem to outsiders, the guidance of Jachemuyelos is what keeps the more fervent and overzealous inquisitors in check; this is not an entity of blind wrath and damnation, but a truly objective…" },
  { n: "Cleansing", sect: "Sanctuary Aeon Rituals", lvl: 1, roll: "Faith + Focus", wyrd: "1", comp: "L, G, P", rng: "Touch", dur: "Prolonged",
    d: "Similar to the Orthodox Rite of Consecration, Cleansing may be used to target people as well as objects, purifying them from evil taint or influence. The Cleansed person resists being affected by psychic powers, Antinomy, Urge or Hubris; half of the casting victory points (rounded up) become a negative penalty for any of these powers attempting to affect the target. This rite has also proven effective in treating wounds when no antiseptic is available. Some Amaltheans perform this rite daily as part of their regular devotional ceremonies. A Cleansed person participating in a rite acts as a…" },
  { n: "Hearth", sect: "Sanctuary Aeon Rituals", lvl: 2, roll: "Passion + Focus", wyrd: "1", comp: "L, G", rng: "Touch", dur: "Prolonged",
    d: "Favored by missionaries on uncivilized worlds, this rite creates what appears to be a campfire, generating enough light to see in a 10 meter radius, and enough heat to boil water or cook food. Unlike the Avesti rite Torchbearing, however, the flame created is not a natural fire; it is not hot enough to fire pottery or smelt ore, and cannot be used to start other fires or ignite flammable materials. No fuel is needed, but a cleared space must be prepared for the rite. Hearth lasts for one span per Wyrd point." },
  { n: "Calming", sect: "Sanctuary Aeon Rituals", lvl: 3, roll: "Calm + Charm", wyrd: "1", comp: "G", rng: "Sight", dur: "Prolonged",
    d: "Considered something of a joke by outsiders, the Calming rite disperses the negative energies of rage, hate, fear and even less negative (but sometimes equally destructive) simple excitement. This rite has prevented many confrontations from escalating to violence, which accounts for the Amaltheans’ reputation as diplomats. In addition, Calming may be effective for targets who are psychically manipulated or possessed by demons; while it does not actually cure or prevent these conditions, it may aid the target by, for instance, silencing the possessed so that the Exorcism may continue…" },
  { n: "Knowing Heart", sect: "Sanctuary Aeon Rituals", lvl: 4, roll: "Perception + Empathy", wyrd: "1", comp: "P", rng: "Sight", dur: "Temporary",
    d: "This rite combines the effects of the psychic abilities Intuit and MindSight, in that it allows the theurge to observe the internal workings of the target’s psyche, both emotional and intellectual. The same restrictions for MindSight apply here, in that only the current state of mind may be read (or felt); subconscious or deeply buried feelings, thoughts or intentions are not disclosed by the Knowing Heart, but may, if the gamemaster allows, be probed for with a critical success." },
  { n: "Fruitful Multiplication", sect: "Sanctuary Aeon Rituals", lvl: 5, roll: "Special (see text)", wyrd: "1", comp: "P", rng: "Touch", dur: "Perpetual",
    d: "Most often used to help feed famine areas, this rite increases the mass of a single targeted substance (such as food, water, cloth, building materials, breathable air, etc.) by a factor equal to the victory points. This rite will not replicate manufactured items, only basic materials. Attempting to use this rite on money or precious metals is grounds for excommunication. To use Fruitful Multiplication, the Theurge rolls Faith+ Vigor or Sleight of Hand." },
  { n: "Restoration", sect: "Sanctuary Aeon Rituals", lvl: 5, roll: "Faith + Stoic Mind", wyrd: "1", comp: "L, G, P", rng: "Touch", dur: "Instant",
    d: "By invoking the compassion of Saint Amalthea, a theurge can restore a body’s spiritual humours to their proper balance: diseases can be cured and poisons expelled. Damage from these ills is not healed but the cause of the problem is removed, allowing patients to recover normally. In the case of disease, the patient’s own immune system wins over the virus, while poisons are expelled from the body, leaving evidence which may be analyzed by investigators attempting to trace the poisoner. Additionally, emotional turbulence can be soothed; the symptoms of neuroses or psychoses are abated, and a…" },
  { n: "Manna from Heaven", sect: "Sanctuary Aeon Rituals", lvl: 6, roll: "Faith + Focus", wyrd: "1", comp: "L, P", rng: "Special (see text)", dur: "Perpetual",
    d: "Casting this rite creates a sufficient amount of food to feed 10 adults for one day per point of Wyrd spent. The quality and variety of food created is dependent on the victory points: 5 or 6 yields fully prepared meals, 3 or 4 a simple but hearty assortment of meats, vegetables, etc., and 1 yielding a chewy dense substance somewhere between jerky and old bread." },
  { n: "Healing Hand of Saint Amalthea", sect: "Sanctuary Aeon Rituals", lvl: 7, roll: "Calm + Physick", wyrd: "1", comp: "L, G, P", rng: "Touch", dur: "Instant",
    d: "By meditating upon Saint Amalthea and reciting all the names of the Pancreator from the Compassionate Truths, the theurge may not only heal back one Vitality point per victory point (as in the Church level 3 Rite Laying On of Hands, above), but may also reattach severed limbs and remove deeply embedded shrapnel, diseased organs or insidious parasites. At the gamemaster’s discretion, the newly dead may be revived with a critical success." },
  { n: "Sanctuary", sect: "Sanctuary Aeon Rituals", lvl: 8, roll: "Faith + Charm", wyrd: "1", comp: "L, G, P", rng: "Special (see text)", dur: "Prolonged",
    d: "Perhaps the foundation of Sanctuary Aeon’s political survival through the ages, this rite acts as a powerful “damper field” preventing any violent or harmful actions. Affecting either a large room or a 10 meter radius around the theurge, any roll made within the Sanctuary using Fight, Melee or Shoot only succeeds on a 1, and any other malevolent or overly aggressive action, such as psychic attack, will be contested by the rite’s roll." },
  { n: "Invitation to Hamomeyelos, Lord of Mercy", sect: "Sanctuary Aeon Rituals", lvl: 9, roll: "Passion + Impress", wyrd: "1", comp: "L, G, P", rng: "Special (see text)", dur: "Special (see text)",
    d: "This exceptionally rare and powerful rite, a closely guarded secret of the order, enables a theurge to contact and summon to the physical world one of the “bodiless powers of the Empyrean,” the compassionate and beneficent intelligence known as Hamomeyelos. According to Eskatonic doctrine, Hamomeyelos rules in the Sixth Emanation from the Celestial Sun, among the ranks of the Virtues. Hamomeyelos has never revealed itself directly to anyone, but always manifests in a tangible physical form under the guise of a good Samaritan, a kindly stranger, a timely messenger, or any manner of helpful…" },
];
